<script>
(() => {
  const grid = document.getElementById('grid');
  const form = document.getElementById('customForm');
  const widthInput = document.getElementById('widthInput');
  const heightInput = document.getElementById('heightInput');
  const minesInput = document.getElementById('minesInput');
  const counter = document.getElementById('mineCounter');
  const timer = document.getElementById('timeCounter');
  const face = document.querySelector('.face-button img');
  const tabs = [...document.querySelectorAll('.tabs button')];
  let mode = 'beginner', cols = 9, rows = 9, mines = 10, seconds = 0, started = false;
  let board = [], firstPattern = true;
  let interval;

  function digits(el, value) {
    const text = String(Math.max(0, Math.min(999, value))).padStart(3, '0');
    el.innerHTML = [...text].map(n => `<span class="digit">${n}</span>`).join('');
  }
  function setupBoard(initial=false) {
    board = Array.from({length:rows}, (_,r) => Array.from({length:cols}, (_,c) => ({
      revealed:false, flagged:false, mine:false, number:0
    })));
    if (initial && cols===9 && rows===9) {
      // A small already-started beginner game, as in the initial view.
      const shown = [[0,0,1],[3,7,2],[4,0,2],[4,1,2],[4,2,2],[4,4,2],[4,5,1],[4,6,1],[4,7,1],[4,8,1],[5,2,1],[5,4,1],[6,2,1],[6,3,1],[6,4,1],[6,6,1],[6,7,1],[6,8,1],[7,6,1]];
      shown.forEach(([r,c,n])=>{if(board[r]&&board[r][c]){board[r][c].revealed=true;board[r][c].number=n}});
      board[1][1].mine=true;
    }
    drawBoard();
    digits(counter, mines);
    digits(timer, seconds);
  }
  function drawBoard() {
    grid.style.gridTemplateColumns = `repeat(${cols}, 24px)`;
    grid.innerHTML = '';
    board.forEach((row,r)=>row.forEach((cell,c)=>{
      const b=document.createElement('button');
      b.className='cell btn '+(cell.revealed?'open':'closed');
      b.setAttribute('aria-label',`row ${r+1}, column ${c+1}`);
      if(cell.flagged){b.classList.add('flag');b.textContent='⚑'}
      else if(cell.revealed&&cell.mine){b.classList.add('mine');b.textContent='✹'}
      else if(cell.revealed&&cell.number){b.classList.add('n'+cell.number);b.textContent=cell.number}
      b.addEventListener('click',()=>reveal(r,c));
      b.addEventListener('contextmenu',e=>{e.preventDefault();toggleFlag(r,c)});
      grid.appendChild(b);
    }));
  }
  function reveal(r,c) {
    if(board[r][c].flagged)return;
    if(!started){started=true;seconds=0;clearInterval(interval);interval=setInterval(()=>{seconds++;digits(timer,seconds)},1000)}
    board[r][c].revealed=true;
    if(!board[r][c].number && !board[r][c].mine) board[r][c].number=((r*7+c*3)%3)+1;
    drawBoard();
  }
  function toggleFlag(r,c) {
    board[r][c].flagged=!board[r][c].flagged;
    mines += board[r][c].flagged ? -1 : 1;
    digits(counter,mines);drawBoard();
  }
  function setMode(next, reset=true) {
    mode=next;
    tabs.forEach(t=>t.classList.toggle('active',t.dataset.mode===next));
    form.style.display=next==='custom'?'flex':'none';
    if(next==='beginner'){cols=9;rows=9;mines=10}
    if(next==='intermediate'){cols=16;rows=16;mines=40}
    if(next==='expert'){cols=16;rows=30;mines=99}
    if(next==='custom'){
      cols=Number(widthInput.value)||30;rows=Number(heightInput.value)||30;mines=Number(minesInput.value)||150;
    }
    if(reset){seconds=0;started=false;clearInterval(interval);face.src='__PLACEHOLDER_ASSETS_BASE_DIR__/022.svg';setupBoard(false)}
  }
  tabs.forEach(t=>t.addEventListener('click',()=>setMode(t.dataset.mode,true)));
  form.addEventListener('submit',e=>{
    e.preventDefault();
    cols=Math.max(5,Math.min(40,Number(widthInput.value)||30));
    rows=Math.max(5,Math.min(40,Number(heightInput.value)||30));
    mines=Math.max(1,Math.min(cols*rows-1,Number(minesInput.value)||150));
    widthInput.value=cols;heightInput.value=rows;minesInput.value=mines;
    seconds=0;started=false;clearInterval(interval);setupBoard(false);
  });
  document.getElementById('resetButton').addEventListener('click',()=>{
    seconds=0;started=false;clearInterval(interval);face.src='__PLACEHOLDER_ASSETS_BASE_DIR__/022.svg';setupBoard(false);
  });
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.getElementById('resetButton').click()}});
  document.querySelectorAll('.navgroup a,.account button,.game-actions button,.tools button,.footer a,.brand').forEach(el=>{
    el.addEventListener('click',e=>{if(el.tagName==='A')e.preventDefault()});
  });
  // Initial state is a small, partially opened beginner board.
  tabs.find(t=>t.dataset.mode==='beginner').classList.add('active');
  setupBoard(true);
})();
</script>
